import {chromium} from '@playwright/test';
const browser=await chromium.launch();
try {
 const page=await browser.newPage({viewport:{width:1280,height:800}});
 await page.setContent('<div id="root" tabindex="0"><span id="start">Visible start </span><div id="hidden" style="content-visibility:hidden;contain-intrinsic-size:auto 30px">UNPAINTED SOURCE</div><span id="end"> Visible end</span></div>');
 const result=await page.evaluate(()=>{
  const root=document.querySelector('#root'),range=document.createRange();
  range.setStart(document.querySelector('#start').firstChild,0);range.setEnd(document.querySelector('#end').firstChild,12);
  getSelection().removeAllRanges();getSelection().addRange(range);
  return {canonical:root.textContent,selected:getSelection().toString(),rectangles:[...range.getClientRects()].map(r=>({x:r.x,y:r.y,width:r.width,height:r.height})),hiddenStyle:{contentVisibility:getComputedStyle(document.querySelector('#hidden')).contentVisibility,display:getComputedStyle(document.querySelector('#hidden')).display,visibility:getComputedStyle(document.querySelector('#hidden')).visibility}};
 });
 console.log(JSON.stringify(result));
} finally {await browser.close();}
